INSERT INTO "Images" ("Url", "AltText", "IsMain", "DestinationId", "CreatedAt")
SELECT s."Url", s."AltText", s."IsMain", d."Id", NOW()
FROM source s
JOIN "Destinations" d ON d."Name" = s."DestinationName";

